/**
 * ByteFlow Configuration & SDK — UI GEN 2.0
 *
 * v2 generated apps authenticate with the account-level **ByteFlow API key**
 * (the keys managed in the ByteFlow profile "API Keys" tab). The key is
 * exchanged at runtime for a short-lived WebSocket session token — it is never
 * sent to ByteFlow's namespaces directly.
 *
 * The key is read from `VITE_BYTEFLOW_API_KEY` (a gitignored `.env.local`
 * written at project-creation time, and the same file the secrets-management
 * panel manages), so it is NOT committed in this source file. Note: Vite
 * inlines `VITE_*` vars into the built bundle, so the key is still public in the
 * shipped app — `.env.local` keeps it out of git/source, not out of the client.
 * Revoke from the profile if it leaks.
 *
 * The `BYTEFLOW_CONFIG` object below is rewritten at project-creation time by
 * the backend (`inject_vite_react_config_v2`) — everything between the
 * BYTEFLOW_CONFIG_START / BYTEFLOW_CONFIG_END sentinels is replaced. The SDK
 * functions are NOT regenerated, so this file is the single source of truth
 * for the SDK contract.
 */

// Node data structure including config for parameter overrides
export interface WorkflowNodeData {
  label?: string;
  config?: Record<string, any>;
  connectorType?: string;
  [key: string]: any;
}

export interface WorkflowNode {
  id: string;
  type: string;
  name?: string;
  data?: WorkflowNodeData;
  position?: { x: number; y: number };
}

export interface WorkflowEdge {
  id?: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
}

// Input schema field definition for parameter overrides
export interface InputSchemaField {
  nodeId: string;
  nodeLabel: string;
  field: string;
  label: string;
  type: 'string' | 'number' | 'boolean' | 'select' | 'multiline';
  defaultValue?: any;
  options?: string[];  // For select type
  description?: string;
}

export interface InputSchema {
  version: string;
  fields: InputSchemaField[];
}

// Stored backend schemas use snake_case and may carry extra form metadata.
// Public accessors below normalize these records to InputSchemaField.
export interface RawInputSchema {
  version: string;
  fields: Array<InputSchemaField | Record<string, unknown>>;
  [key: string]: unknown;
}

// Server-derived capability flags injected into BYTEFLOW_CONFIG. Only the fields
// that can't be cheaply derived client-side live here; getCapabilities(workflowId) composes
// the rest (hasChat, hasFileUpload, inputFields) from existing config.
export interface CapabilityFlags {
  schedulable: boolean;             // safe to expose a "run on a schedule" control
  hasHITLAgents: boolean;           // has agent nodes that may ask the user mid-run
  specializedAgentNodes: string[];  // node ids that stream rich agentProgressData
}

// The full capability manifest the generated app reads to decide which workflow
// surfaces to build. See the byteflow-workflow-ui skill (capability-manifest.md).
export interface Capabilities extends CapabilityFlags {
  hasChat: boolean;                 // workflow has a chat_trigger → build a chat UI
  hasFileUpload: boolean;           // workflow has file_upload node(s)
  inputFields: InputSchemaField[];  // overridable params → build a run form
}

// Baked (project-creation time) snapshot of a file_upload node. Initial paint
// only — the live state comes from getFileUploadNodes(workflowId).
export interface FileUploadNodeConfig {
  nodeId: string;
  label: string;
  accept: string;        // comma-separated extension list for <input accept=…>
  multiple: boolean;     // node currently holds a folder upload
  currentFile: { filename: string; size: number; fileType: string } | null;
}

export interface ByteflowConfig {
  projectId: string;
  workflowId: string;
  workflowName: string;
  apiKey: string;        // Account-level ByteFlow API key (from VITE_BYTEFLOW_API_KEY) — exchanged for a short-lived WS token
  apiUrl: string;        // Backend URL for token exchange, execution, and scheduling
  generationVersion: 'v2';
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  hasChatTrigger: boolean;
  fileUploadNodes: FileUploadNodeConfig[];
  inputSchema: RawInputSchema;
  capabilities: CapabilityFlags;
}

